import{bV as e,aL as s,u as i,G as n}from"./chunks/framework.DT-LCgF3.js";const b=JSON.parse('{"title":"Office 2003 二进制文件格式","description":"","frontmatter":{"date":"2026-09-10T14:16:05.000Z","title":"Office 2003 二进制文件格式","categories":["Format","Office"],"permalink":"/pages/65ea19"},"headers":[],"relativePath":"Format/Office 2003二进制格式.md","filePath":"Format/Office 2003二进制格式.md","lastUpdated":1789633483000}'),l={name:"Format/Office 2003二进制格式.md"};function t(p,a,d,o,r,c){return s(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="office-2003-二进制文件格式" tabindex="-1">Office 2003 二进制文件格式 <a class="header-anchor" href="#office-2003-二进制文件格式" aria-label="Permalink to &quot;Office 2003 二进制文件格式&quot;">​</a></h1><p>Office 2003 及更早版本的 Word、Excel、PowerPoint 文档，通常使用一套基于 OLE Compound File 的二进制文件格式。常见扩展名包括：</p><ul><li>Word：<code>.doc</code></li><li>Excel：<code>.xls</code></li><li>PowerPoint：<code>.ppt</code></li><li>复合文档：<code>.vsd</code>、<code>.msg</code>、<code>.mpp</code> 等</li></ul><p>这些文件与 Office 2007 之后常见的 <code>.docx</code>、<code>.xlsx</code>、<code>.pptx</code> 不同。后者本质上是 ZIP 容器中的 XML 文件，而 Office 2003 格式通常是一个二进制复合文件。</p><h2 id="一、什么是-ole-compound-file" tabindex="-1">一、什么是 OLE Compound File <a class="header-anchor" href="#一、什么是-ole-compound-file" aria-label="Permalink to &quot;一、什么是 OLE Compound File&quot;">​</a></h2><p>OLE Compound File 的全称是 <strong>Object Linking and Embedding Compound File</strong>，中文通常称为 OLE 复合文件、复合文档或 Compound File Binary Format（CFBF）。</p><p>它可以把多个逻辑对象组织在一个文件中，结构上类似一个小型文件系统：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Compound File</span></span>
<span class="line"><span>├── Storage（类似目录）</span></span>
<span class="line"><span>│   ├── Storage</span></span>
<span class="line"><span>│   └── Stream（类似文件）</span></span>
<span class="line"><span>├── Stream</span></span>
<span class="line"><span>├── Stream</span></span>
<span class="line"><span>└── 目录信息、分配表、元数据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>因此，<code>.doc</code> 文件并不是一段从头到尾连续排列的文本，而是由多个 Stream 和 Storage 组成。不同 Office 应用会在这些 Stream 中保存正文、样式、表格、图片、宏、嵌入对象和文档属性等内容。</p><h2 id="二、文件头特征" tabindex="-1">二、文件头特征 <a class="header-anchor" href="#二、文件头特征" aria-label="Permalink to &quot;二、文件头特征&quot;">​</a></h2><p>标准 OLE 复合文件通常以以下 8 个字节开头：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D0 CF 11 E0 A1 B1 1A E1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>用十六进制工具查看文件头：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xxd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> document.doc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>也可以使用 PowerShell：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Format-Hex</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path .\\document.doc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Count </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果文件头以 <code>D0 CF 11 E0 A1 B1 1A E1</code> 开始，通常可以判断它属于 OLE Compound File。但需要注意：文件头只能说明容器类型，不能单独证明文件一定是 Word、Excel 或 PowerPoint 文档。</p><h2 id="三、ole-复合文件的主要结构" tabindex="-1">三、OLE 复合文件的主要结构 <a class="header-anchor" href="#三、ole-复合文件的主要结构" aria-label="Permalink to &quot;三、OLE 复合文件的主要结构&quot;">​</a></h2><h3 id="_1-header" tabindex="-1">1. Header <a class="header-anchor" href="#_1-header" aria-label="Permalink to &quot;1. Header&quot;">​</a></h3><p>Header 位于文件起始位置，记录整个复合文件的基本参数，例如：</p><ul><li>文件签名；</li><li>版本号；</li><li>字节序；</li><li>扇区大小；</li><li>Mini Stream 扇区大小；</li><li>FAT、DIFAT、Directory 等结构的位置和数量；</li><li>根 Storage 的信息。</li></ul><p>常见 OLE 文件使用 512 字节扇区。较大的版本可能使用 4096 字节扇区，具体数值应以 Header 中的字段为准。</p><h3 id="_2-fat-file-allocation-table" tabindex="-1">2. FAT（File Allocation Table） <a class="header-anchor" href="#_2-fat-file-allocation-table" aria-label="Permalink to &quot;2. FAT（File Allocation Table）&quot;">​</a></h3><p>FAT 用于描述普通扇区之间的链接关系。一个 Stream 可能并不连续存储在文件中，FAT 会把它的多个扇区串联起来，类似传统文件系统中的簇链。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stream 起始扇区</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>  Sector 12 ──&gt; Sector 35 ──&gt; Sector 36 ──&gt; End Of Chain</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>常见特殊值包括：</p><ul><li><code>FREESECT</code>：空闲扇区；</li><li><code>FATSECT</code>：当前扇区用于保存 FAT；</li><li><code>DIFSECT</code>：当前扇区用于保存 DIFAT；</li><li><code>ENDOFCHAIN</code>：链结束；</li><li><code>NOSTREAM</code>：没有对应 Stream。</li></ul><h3 id="_3-difat-double-indirect-fat" tabindex="-1">3. DIFAT（Double-Indirect FAT） <a class="header-anchor" href="#_3-difat-double-indirect-fat" aria-label="Permalink to &quot;3. DIFAT（Double-Indirect FAT）&quot;">​</a></h3><p>当文件较大、FAT 扇区较多时，Header 不能容纳所有 FAT 扇区的位置，此时使用 DIFAT 保存更多 FAT 扇区索引。它可以理解为 FAT 的索引表，用于帮助解析器找到完整的 FAT。</p><h3 id="_4-directory" tabindex="-1">4. Directory <a class="header-anchor" href="#_4-directory" aria-label="Permalink to &quot;4. Directory&quot;">​</a></h3><p>Directory 保存 Storage 和 Stream 的目录项。每个目录项通常包含：</p><ul><li>名称；</li><li>对象类型；</li><li>左、右、子节点关系；</li><li>CLSID；</li><li>创建时间和修改时间；</li><li>起始扇区；</li><li>Stream 大小。</li></ul><p>Directory 中的节点关系通常组织成红黑树，用于快速定位对象。</p><h3 id="_5-minifat-与-mini-stream" tabindex="-1">5. MiniFAT 与 Mini Stream <a class="header-anchor" href="#_5-minifat-与-mini-stream" aria-label="Permalink to &quot;5. MiniFAT 与 Mini Stream&quot;">​</a></h3><p>对于体积较小的 Stream，直接使用完整扇区会造成空间浪费。OLE 会把小于特定阈值的 Stream 放入 Mini Stream，再使用 MiniFAT 管理这些小块。</p><p>常见实现中，Stream 小于 4096 字节时可能使用 Mini Stream，但实际判断应以格式字段和解析器规则为准，不应仅根据文件大小进行猜测。</p><h3 id="_6-root-entry" tabindex="-1">6. Root Entry <a class="header-anchor" href="#_6-root-entry" aria-label="Permalink to &quot;6. Root Entry&quot;">​</a></h3><p>Root Entry 是整个 OLE 复合文件的根 Storage，通常名称为 <code>Root Entry</code>。它负责管理 Mini Stream，并作为所有 Storage 和 Stream 的根节点。</p><h2 id="四、word、excel、powerpoint-的差异" tabindex="-1">四、Word、Excel、PowerPoint 的差异 <a class="header-anchor" href="#四、word、excel、powerpoint-的差异" aria-label="Permalink to &quot;四、Word、Excel、PowerPoint 的差异&quot;">​</a></h2><p>三类文档可以共用 OLE 容器，但内部 Stream 的组织方式和业务数据格式不同。</p><table tabindex="0"><thead><tr><th>文件类型</th><th>常见扩展名</th><th>主要内容</th></tr></thead><tbody><tr><td>Word 文档</td><td><code>.doc</code></td><td>文本、段落、样式、表格、图片、批注、修订记录、宏</td></tr><tr><td>Excel 工作簿</td><td><code>.xls</code></td><td>工作表、单元格、公式、格式、图表、名称、宏</td></tr><tr><td>PowerPoint 演示文稿</td><td><code>.ppt</code></td><td>幻灯片、文本框、图片、形状、动画、备注、宏</td></tr></tbody></table><p>容器层可以通过 OLE 解析，但要完整读取正文或业务结构，还需要对应的文档格式解析器。例如，读取 Word 正文不能只把 OLE Stream 当作普通文本，因为内容通常还包含二进制记录、压缩数据或复杂的偏移关系。</p><h3 id="word-doc" tabindex="-1">Word <code>.doc</code> <a class="header-anchor" href="#word-doc" aria-label="Permalink to &quot;Word \`.doc\`&quot;">​</a></h3><p>Word 二进制文档中常见 <code>WordDocument</code> Stream，以及用于保存表格、对象和其他数据的相关 Stream。正文可能涉及 FIB（File Information Block）、Piece Table 等结构，需要结合 Word Binary File Format 规范解析。</p><h3 id="excel-xls" tabindex="-1">Excel <code>.xls</code> <a class="header-anchor" href="#excel-xls" aria-label="Permalink to &quot;Excel \`.xls\`&quot;">​</a></h3><p>Excel 97-2003 工作簿使用 BIFF（Binary Interchange File Format）记录保存数据。工作表通常由一系列记录组成，每条记录包含记录类型、长度和数据内容。</p><p>典型记录可能包括：</p><ul><li><code>BOF</code>：流或子文档开始；</li><li><code>EOF</code>：流或子文档结束；</li><li><code>SST</code>：共享字符串表；</li><li><code>NUMBER</code>：数值单元格；</li><li><code>LABELSST</code>：引用共享字符串的单元格；</li><li><code>FORMULA</code>：公式单元格。</li></ul><h3 id="powerpoint-ppt" tabindex="-1">PowerPoint <code>.ppt</code> <a class="header-anchor" href="#powerpoint-ppt" aria-label="Permalink to &quot;PowerPoint \`.ppt\`&quot;">​</a></h3><p>PowerPoint 二进制格式以记录树保存演示文稿内容，记录中可能包含幻灯片、文本、图形、媒体、备注和动画信息。由于其对象层级较复杂，通常使用专门的 PowerPoint 解析库，而不是手动按字节处理。</p><h2 id="五、与-office-open-xml-的区别" tabindex="-1">五、与 Office Open XML 的区别 <a class="header-anchor" href="#五、与-office-open-xml-的区别" aria-label="Permalink to &quot;五、与 Office Open XML 的区别&quot;">​</a></h2><p>Office 2007 以后引入了 Office Open XML（OOXML）格式，常见扩展名为 <code>.docx</code>、<code>.xlsx</code> 和 <code>.pptx</code>。</p><table tabindex="0"><thead><tr><th>对比项</th><th>Office 2003 二进制格式</th><th>OOXML 格式</th></tr></thead><tbody><tr><td>容器</td><td>OLE Compound File</td><td>ZIP</td></tr><tr><td>内容</td><td>二进制记录和 Stream</td><td>XML、媒体和关系文件</td></tr><tr><td>常见扩展名</td><td><code>.doc</code>、<code>.xls</code>、<code>.ppt</code></td><td><code>.docx</code>、<code>.xlsx</code>、<code>.pptx</code></td></tr><tr><td>可读性</td><td>不适合直接阅读</td><td>XML 部分可直接查看</td></tr><tr><td>解析方式</td><td>需要 OLE + 专用二进制格式解析器</td><td>解压后按 XML 和关系文件解析</td></tr><tr><td>宏文件</td><td>通常嵌入 OLE 容器</td><td>通常使用 <code>.docm</code>、<code>.xlsm</code>、<code>.pptm</code></td></tr><tr><td>文件损坏定位</td><td>需要分析扇区链和内部记录</td><td>通常可以定位到具体 XML 部件</td></tr><tr><td>兼容性</td><td>老版本 Office 兼容性好</td><td>现代 Office 默认格式</td></tr></tbody></table><p>可以使用 <code>file</code> 和 <code>unzip</code> 对两类文件做初步区分：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> document.doc</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> document.docx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> document.docx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>.docx</code> 文件可以用 ZIP 工具列出内容，常见目录包括：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Content_Types].xml</span></span>
<span class="line"><span>_rels/</span></span>
<span class="line"><span>docProps/</span></span>
<span class="line"><span>word/</span></span>
<span class="line"><span>xl/</span></span>
<span class="line"><span>ppt/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>而 <code>.doc</code> 通常不能直接按 ZIP 文件处理。</p><h2 id="六、如何识别和验证文件格式" tabindex="-1">六、如何识别和验证文件格式 <a class="header-anchor" href="#六、如何识别和验证文件格式" aria-label="Permalink to &quot;六、如何识别和验证文件格式&quot;">​</a></h2><h3 id="_1-不要只相信扩展名" tabindex="-1">1. 不要只相信扩展名 <a class="header-anchor" href="#_1-不要只相信扩展名" aria-label="Permalink to &quot;1. 不要只相信扩展名&quot;">​</a></h3><p>扩展名可以被任意修改。例如，一个 OLE 文件可以被重命名为 <code>.jpg</code>，一个 ZIP/OOXML 文件也可以被重命名为 <code>.doc</code>。安全分析时应优先查看文件头和容器结构。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suspicious-file</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xxd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suspicious-file</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_2-校验-ole-结构" tabindex="-1">2. 校验 OLE 结构 <a class="header-anchor" href="#_2-校验-ole-结构" aria-label="Permalink to &quot;2. 校验 OLE 结构&quot;">​</a></h3><p>Linux 下可以使用 <code>olefile</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> olefile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PY&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import olefile</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">path = &quot;document.doc&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">if olefile.isOleFile(path):</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    with olefile.OleFileIO(path) as ole:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        for entry in ole.listdir():</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            print(&quot;/&quot;.join(entry))</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">else:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    print(&quot;不是有效的 OLE Compound File&quot;)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PY</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>也可以使用 <code>7z</code> 查看容器中的目录：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">7z</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> document.doc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>7z</code> 能否完整列出内容取决于文件结构和工具版本，因此不能替代专业解析器。</p><h3 id="_3-使用专用工具提取文档信息" tabindex="-1">3. 使用专用工具提取文档信息 <a class="header-anchor" href="#_3-使用专用工具提取文档信息" aria-label="Permalink to &quot;3. 使用专用工具提取文档信息&quot;">​</a></h3><p>常见工具包括：</p><ul><li><code>olefile</code>：Python OLE 容器解析库；</li><li><code>oletools</code>：分析 OLE、VBA 宏和嵌入对象；</li><li><code>oledump.py</code>：按 Stream 查看 OLE 文件内容；</li><li><code>mraptor</code>：检测 VBA 宏的潜在恶意行为特征；</li><li><code>exiftool</code>：提取文档元数据；</li><li>LibreOffice headless：执行格式转换和批量处理；</li><li>Apache POI：Java 生态中的 Office 文档处理库。</li></ul><p>例如使用 <code>olevba</code> 提取 VBA 宏：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">olevba</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suspicious.doc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>分析不可信文件时，建议在隔离环境中执行工具，并先计算哈希值保存证据：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suspicious.doc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suspicious.doc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">olevba</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suspicious.doc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="七、格式转换建议" tabindex="-1">七、格式转换建议 <a class="header-anchor" href="#七、格式转换建议" aria-label="Permalink to &quot;七、格式转换建议&quot;">​</a></h2><h3 id="使用-libreoffice-转换" tabindex="-1">使用 LibreOffice 转换 <a class="header-anchor" href="#使用-libreoffice-转换" aria-label="Permalink to &quot;使用 LibreOffice 转换&quot;">​</a></h3><p>可以在无图形界面的环境中进行转换：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">libreoffice</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --convert-to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --outdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./converted</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> document.doc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">libreoffice</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --convert-to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xlsx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --outdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./converted</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workbook.xls</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">libreoffice</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --convert-to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pptx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --outdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./converted</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> presentation.ppt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>批量转换前应注意：</p><ul><li>复杂排版可能发生变化；</li><li>Excel 公式、宏和外部链接可能受到影响；</li><li>PowerPoint 动画、字体和媒体兼容性需要人工复核；</li><li>转换不等于安全清洗，恶意对象或宏不应在不可信环境中直接打开。</li></ul><h3 id="使用-office-软件另存为" tabindex="-1">使用 Office 软件另存为 <a class="header-anchor" href="#使用-office-软件另存为" aria-label="Permalink to &quot;使用 Office 软件另存为&quot;">​</a></h3><p>在现代 Office 中打开旧格式文件后，可以通过“另存为”转换为 <code>.docx</code>、<code>.xlsx</code> 或 <code>.pptx</code>。如果文件来源不可信，应先在受控环境中分析，不建议直接使用主机上的 Office 打开。</p><h2 id="八、安全分析重点" tabindex="-1">八、安全分析重点 <a class="header-anchor" href="#八、安全分析重点" aria-label="Permalink to &quot;八、安全分析重点&quot;">​</a></h2><p>Office 2003 二进制格式在安全分析中需要重点关注以下内容。</p><h3 id="_1-ole-容器中的宏" tabindex="-1">1. OLE 容器中的宏 <a class="header-anchor" href="#_1-ole-容器中的宏" aria-label="Permalink to &quot;1. OLE 容器中的宏&quot;">​</a></h3><p>旧版 Office 文档常见 VBA 宏。宏可以调用系统命令、访问文件、修改注册表、启动脚本解释器或下载其他载荷。</p><p>宏分析时至少应关注：</p><ul><li><code>AutoOpen</code>、<code>Document_Open</code>、<code>Workbook_Open</code> 等自动执行入口；</li><li><code>Shell</code>、<code>CreateObject</code>、<code>WScript.Shell</code> 等命令执行能力；</li><li><code>URLDownloadToFile</code>、HTTP 请求和网络通信；</li><li>Base64、十六进制、字符串拼接等混淆；</li><li><code>CreateFile</code>、注册表操作和计划任务；</li><li>是否存在嵌入式 OLE 对象或外部链接。</li></ul><h3 id="_2-嵌入对象与外部链接" tabindex="-1">2. 嵌入对象与外部链接 <a class="header-anchor" href="#_2-嵌入对象与外部链接" aria-label="Permalink to &quot;2. 嵌入对象与外部链接&quot;">​</a></h3><p>文档可能嵌入其他文件，或包含指向外部资源的链接。分析时应检查：</p><ul><li>OLE Object Stream；</li><li>Package 对象；</li><li>DDE 相关字段；</li><li>外部模板和远程链接；</li><li>嵌入的脚本、可执行文件或压缩包。</li></ul><h3 id="_3-文件头伪装" tabindex="-1">3. 文件头伪装 <a class="header-anchor" href="#_3-文件头伪装" aria-label="Permalink to &quot;3. 文件头伪装&quot;">​</a></h3><p>扩展名与文件头不一致是恶意样本中常见的伪装方式。检测流程应至少包含：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>扩展名检查</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>文件头检查</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>容器结构检查</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>宏与嵌入对象提取</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>沙箱或隔离环境动态分析</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_4-不要直接打开样本" tabindex="-1">4. 不要直接打开样本 <a class="header-anchor" href="#_4-不要直接打开样本" aria-label="Permalink to &quot;4. 不要直接打开样本&quot;">​</a></h3><p>即使关闭宏，文档解析器本身也可能存在漏洞。处理未知来源的 <code>.doc</code>、<code>.xls</code>、<code>.ppt</code> 时建议：</p><ul><li>使用无网络隔离环境；</li><li>先计算 SHA-256；</li><li>不使用宿主机上的敏感凭据；</li><li>禁止自动加载外部资源；</li><li>不在分析机上启用宏；</li><li>保存原始样本，分析副本单独处理；</li><li>对提取出的嵌入文件继续进行类型和哈希检查。</li></ul><h2 id="九、常见判断误区" tabindex="-1">九、常见判断误区 <a class="header-anchor" href="#九、常见判断误区" aria-label="Permalink to &quot;九、常见判断误区&quot;">​</a></h2><h3 id="误区一-doc-一定是-office-2003-格式" tabindex="-1">误区一：<code>.doc</code> 一定是 Office 2003 格式 <a class="header-anchor" href="#误区一-doc-一定是-office-2003-格式" aria-label="Permalink to &quot;误区一：\`.doc\` 一定是 Office 2003 格式&quot;">​</a></h3><p><code>.doc</code> 主要表示 Word 文档扩展名，但并不保证内部一定是标准 Office 2003 二进制格式。文件可能被伪造、损坏、重命名，甚至是其他容器。</p><h3 id="误区二-看到-ole-文件头就一定有宏" tabindex="-1">误区二：看到 OLE 文件头就一定有宏 <a class="header-anchor" href="#误区二-看到-ole-文件头就一定有宏" aria-label="Permalink to &quot;误区二：看到 OLE 文件头就一定有宏&quot;">​</a></h3><p>OLE 只是容器格式，许多正常文档和非 Office 文件同样使用 OLE。检测宏需要继续枚举 Stream，并分析 VBA 项目和嵌入对象。</p><h3 id="误区三-转换成-docx-就完成安全清洗" tabindex="-1">误区三：转换成 <code>.docx</code> 就完成安全清洗 <a class="header-anchor" href="#误区三-转换成-docx-就完成安全清洗" aria-label="Permalink to &quot;误区三：转换成 \`.docx\` 就完成安全清洗&quot;">​</a></h3><p>格式转换可能移除部分宏或对象，但不应将其当作可靠的安全边界。转换工具本身也可能解析恶意数据，转换前后的文件都应重新检查。</p><h3 id="误区四-把二进制文件当文本搜索" tabindex="-1">误区四：把二进制文件当文本搜索 <a class="header-anchor" href="#误区四-把二进制文件当文本搜索" aria-label="Permalink to &quot;误区四：把二进制文件当文本搜索&quot;">​</a></h3><p>直接用文本编辑器搜索 <code>.doc</code>、<code>.xls</code>、<code>.ppt</code>，通常只能看到零散字符串，无法正确理解记录、偏移和 Stream 关系。应先识别容器，再使用对应解析器。</p><h2 id="十、总结" tabindex="-1">十、总结 <a class="header-anchor" href="#十、总结" aria-label="Permalink to &quot;十、总结&quot;">​</a></h2><p>Office 2003 格式的核心可以概括为：</p><ol><li><code>.doc</code>、<code>.xls</code>、<code>.ppt</code> 通常使用 OLE Compound File 作为容器；</li><li>OLE 容器内部由 Header、FAT、DIFAT、Directory、MiniFAT、Mini Stream 和多个 Stream 组成；</li><li>Word、Excel、PowerPoint 在同一容器模型下使用不同的二进制业务格式；</li><li>文件头 <code>D0 CF 11 E0 A1 B1 1A E1</code> 可作为 OLE 文件的初步识别特征；</li><li>与 OLE 二进制格式相比，Office Open XML 使用 ZIP + XML 结构，更适合解压和部件化分析；</li><li>安全分析不能只看扩展名，应结合文件头、容器结构、宏、嵌入对象和外部链接综合判断。</li></ol><p>在实际工作中，可以把分析流程固定为：<strong>识别文件头 → 判断容器 → 枚举内部对象 → 提取宏和嵌入文件 → 计算哈希 → 隔离环境分析 → 必要时转换并复核</strong>。</p>`,111)])])}const u=e(l,[["render",t]]);export{b as __pageData,u as default};
